func TestConcurrentUploads(t *testing.T) {
	var wg sync.WaitGroup
	for i := 0; i < 32; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); handleUpload(testPayload(5 << 20)) }()
	}
	wg.Wait()
}

